public class OuterService {
    private final String serviceName = "PaymentProcessor";

    // 1. Static Nested Class (Ideal for Builders or independent helpers)
    public static class ServiceConfig {
        private int timeoutMs = 5000;
        public ServiceConfig timeout(int timeoutMs) {
            this.timeoutMs = timeoutMs;
            return this;
        }
    }

    // 2. Inner Class (Has access to OuterService.this)
    public class InternalWorker {
        public void execute() {
            System.out.println("Running worker for: " + serviceName);
        }
    }

    public void process() {
        // 3. Local Class (Defined inside a method block)
        final String transactionId = "TXN-9988";
        class LocalValidator {
            boolean validate() {
                return transactionId != null && !transactionId.isEmpty();
            }
        }

        LocalValidator validator = new LocalValidator();
        if (validator.validate()) {
            // 4. Anonymous Class (Inline implementation)
            Runnable task = new Runnable() {
                @Override
                public void run() {
                    System.out.println("Executing task for transaction: " + transactionId);
                }
            };
            new Thread(task).start();
        }
    }
}
